sysauto_script.script:
function createdThisMonth(date){
  var year = date.substring(0,4);
  var month = parseInt(date.substring(5,7)) - 1;
  var day = date.substring(8,10);
	var reportCreationDate = new Date(year,month,day);
	var today = new Date();
	if (today.getMonth() == reportCreationDate.getMonth()){
		return true;
	}
	else
	{
		return false;
	}

}

function getRemainingDays() {
	var date = new Date();
	var time = new Date(date.getTime());
	time.setMonth(date.getMonth() + 1);
	time.setDate(0);
	var days =time.getDate() > date.getDate() ? time.getDate() - date.getDate() : 0;
	return days;
}


if (getRemainingDays() == 2 || getRemainingDays() == 7){
	//Send emails
	var gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
	gr.addEncodedQuery('state=903');
	gr.query();
	while (gr.next()) {
		if (createdThisMonth(gr.getValue("sys_created_on")) == true){
			//Triggers notification called 'Draft workplace inspection report reminder'
			gs.eventQueue('x_hccc_hoc_ohs.workplace.inspection.reminder',gr);
		}
	}
}
